import React, { useState, useEffect } from 'react';
import { statisticsApi } from '../services/api';
import { format, subDays } from 'date-fns';
import StatisticsHeader from './StatisticsHeader';
import StatisticsFilters from './StatisticsFilters';
import StatisticsView from './StatisticsView';
import UserStatisticsTable from './UserStatisticsTable';
import './ActivityStatistics.css';

const ActivityStatistics = () => {
  // 통계 타입: 'daily' 또는 'monthly'
  const [statisticsType, setStatisticsType] = useState('daily');

  // 검색 조건
  const [filters, setFilters] = useState({
    logType: '',
    userId: '',
    department: '',
    ip: ''
  });

  // 날짜 범위 (일별)
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  // 연도/월 (월별)
  const [year, setYear] = useState(new Date().getFullYear());
  const [month, setMonth] = useState(new Date().getMonth() + 1);

  // 통계 데이터
  const [statisticsData, setStatisticsData] = useState(null);
  const [userStatistics, setUserStatistics] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // 콤보박스 데이터
  const [userList, setUserList] = useState([]);
  const [departmentList, setDepartmentList] = useState([]);
  const [ipList, setIpList] = useState([]);

  // 뷰 타입: 'chart' 또는 'table'
  const [viewType, setViewType] = useState('chart');

  // 표 정렬
  const [sortConfig, setSortConfig] = useState({ key: null, direction: 'asc' });

  // 사용자별 통계 정렬
  const [userSortConfig, setUserSortConfig] = useState({ key: null, direction: 'asc' });

  // 초기 날짜 설정
  useEffect(() => {
    const today = new Date();
    const sevenDaysAgo = new Date(today);
    sevenDaysAgo.setDate(today.getDate() - 7);

    setStartDate(format(sevenDaysAgo, 'yyyy-MM-dd'));
    setEndDate(format(today, 'yyyy-MM-dd'));
  }, []);

  // 콤보박스 데이터 로드
  useEffect(() => {
    loadComboBoxData();
  }, []);

  const loadComboBoxData = async () => {
    try {
      const [usersRes, departmentsRes, ipsRes] = await Promise.all([
        statisticsApi.getUserList(),
        statisticsApi.getDepartmentList(),
        statisticsApi.getIpList()
      ]);

      if (usersRes.success) {
        setUserList(usersRes.data || []);
      }
      if (departmentsRes.success) {
        setDepartmentList(departmentsRes.data || []);
      }
      if (ipsRes.success) {
        setIpList(ipsRes.data || []);
      }
    } catch (error) {
      console.error('콤보박스 데이터 로드 중 오류:', error);
    }
  };

  const handleSearch = async () => {
    setLoading(true);
    setError(null);

    try {
      let response;

      if (statisticsType === 'daily') {
        if (!startDate || !endDate) {
          setError('시작일과 종료일을 선택해주세요.');
          setLoading(false);
          return;
        }
        response = await statisticsApi.getDailyStatistics(startDate, endDate, filters);
      } else {
        if (!year || !month) {
          setError('연도와 월을 선택해주세요.');
          setLoading(false);
          return;
        }
        response = await statisticsApi.getMonthlyStatistics(year, month, filters);
      }

      if (response.success) {
        setStatisticsData(response.data);
      } else {
        setError(response.error || '통계 조회 중 오류가 발생했습니다.');
      }
    } catch (error) {
      console.error('통계 조회 중 오류:', error);
      setError('통계 조회 중 오류가 발생했습니다.');
    } finally {
      setLoading(false);
    }
  };

  const handleExport = async () => {
    try {
      let queryParams;

      if (statisticsType === 'daily') {
        queryParams = {
          startDate,
          endDate,
          ...filters
        };
      } else {
        queryParams = {
          year,
          month,
          ...filters
        };
      }

      const blob = await statisticsApi.exportStatistics(statisticsType, queryParams);

      // 파일 다운로드
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `activity_statistics_${statisticsType}_${new Date().toISOString().split('T')[0]}.csv`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (error) {
      console.error('Excel 다운로드 중 오류:', error);
      alert('Excel 다운로드 중 오류가 발생했습니다.');
    }
  };

  const handleSort = (key) => {
    let direction = 'asc';
    if (sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  return (
    <div className="activity-statistics">
      <h2>활동 로그 통계</h2>

      <StatisticsHeader
        statisticsType={statisticsType}
        onTypeChange={setStatisticsType}
        startDate={startDate}
        endDate={endDate}
        onStartDateChange={setStartDate}
        onEndDateChange={setEndDate}
        year={year}
        month={month}
        onYearChange={setYear}
        onMonthChange={setMonth}
      />

      <StatisticsFilters
        filters={filters}
        onFiltersChange={setFilters}
        userList={userList}
        departmentList={departmentList}
        ipList={ipList}
      />

      {error && (
        <div className="error-message">
          {error}
        </div>
      )}

      {statisticsData && (
        <StatisticsView
          statisticsData={statisticsData}
          statisticsType={statisticsType}
          viewType={viewType}
          onViewTypeChange={setViewType}
          onExport={handleExport}
          sortConfig={sortConfig}
          onSort={handleSort}
          onSearch={handleSearch}
          loading={loading}
        />
      )}
    </div>
  );
};

export default ActivityStatistics;
